package com.electricpro.app;
import android.app.*; import android.os.*; import android.graphics.Color; import android.graphics.Typeface; import android.graphics.drawable.GradientDrawable; import android.view.Gravity; import android.widget.*;
public class MainActivity extends Activity {
 int navy=Color.rgb(12,22,43), panel=Color.rgb(24,38,64), yellow=Color.rgb(255,196,54), white=Color.rgb(246,248,252), muted=Color.rgb(177,190,210); LinearLayout root;
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(navy);getWindow().setNavigationBarColor(navy);home();}
 int dp(int x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
 GradientDrawable shape(int c){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(16));return d;}
 TextView txt(String s,int z,int c,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);if(bold)t.setTypeface(null,Typeface.BOLD);return t;}
 void base(String sub){root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(20),dp(20),dp(20),dp(20));root.setBackgroundColor(navy);ScrollView sc=new ScrollView(this);sc.addView(root);setContentView(sc);root.addView(txt("⚡  ЭЛЕКТРИК PRO",24,yellow,true));TextView s=txt(sub,14,muted,false);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(8);p.bottomMargin=dp(22);root.addView(s,p);}
 void card(String title,String desc,String icon,Runnable r){LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(dp(18),dp(16),dp(18),dp(16));c.setBackground(shape(panel));c.addView(txt(icon+"  "+title,18,yellow,true));TextView d=txt(desc,14,muted,false);LinearLayout.LayoutParams q=new LinearLayout.LayoutParams(-1,-2);q.topMargin=dp(8);c.addView(d,q);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(12);root.addView(c,p);c.setOnClickListener(v->r.run());}
 void btn(String label,Runnable r){TextView b=txt(label,16,navy,true);b.setGravity(Gravity.CENTER);b.setPadding(dp(12),dp(15),dp(12),dp(15));b.setBackground(shape(yellow));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(8);p.bottomMargin=dp(8);root.addView(b,p);b.setOnClickListener(v->r.run());}
 void home(){base("Практические инструменты для электрика");TextView w=txt("Всё необходимое\nдля работы с электрикой",28,white,true);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(20);root.addView(w,p);card("Калькулятор проводов","Расчёт тока и мощности","⌁",()->calc());card("Освещение","Расчёт освещённости помещения","☼",()->light());card("Справочник электрика","Формулы и основные значения","▤",()->reference());card("Безопасность","Основные правила электробезопасности","⚠",()->safety());}
 EditText field(String hint){EditText e=new EditText(this);e.setSingleLine(true);e.setHint(hint);e.setTextColor(white);e.setHintTextColor(muted);e.setPadding(dp(12),dp(8),dp(12),dp(8));e.setBackground(shape(panel));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(8);root.addView(e,p);return e;}
 double num(EditText e){try{return Double.parseDouble(e.getText().toString().trim().replace(',','.'));}catch(Exception x){msg("Введите число");return 0;}}
 void calc(){base("Калькулятор проводов");btn("← На главную",()->home());root.addView(txt("Мощность = напряжение × ток",18,white,true));EditText u=field("Напряжение, В"),i=field("Ток, А");btn("Рассчитать мощность",()->result("Мощность",num(u)*num(i),"Вт"));EditText pp=field("Мощность, Вт"),uu=field("Напряжение, В");btn("Рассчитать ток",()->{double v=num(uu);if(v>0)result("Ток",num(pp)/v,"А");else msg("Напряжение должно быть больше нуля");});card("Важно","Выбор кабеля зависит от условий прокладки и защиты. Эти расчёты не заменяют проект.","ⓘ",()->{});}
 void light(){base("Калькулятор освещения");btn("← На главную",()->home());EditText a=field("Площадь помещения, м²"),l=field("Освещённость, лк");btn("Рассчитать световой поток",()->{double aa=num(a),ll=num(l);if(aa>0&&ll>0)result("Ориентировочный поток",aa*ll,"лм");else msg("Введите значения больше нуля");});card("Примечание","Упрощённый расчёт не учитывает высоту монтажа, потери светильников и отражение поверхностей.","ⓘ",()->{});}
 void reference(){base("Справочник электрика");btn("← На главную",()->home());card("Закон Ома","I = U / R — ток равен напряжению, делённому на сопротивление.","Ω",()->{});card("Электрическая мощность","P = U × I — мощность равна напряжению, умноженному на ток.","ϟ",()->{});card("Сопротивление","R = U / I","Ω",()->{});card("Переменный ток","P ≈ U × I × cos φ для однофазной нагрузки.","∿",()->{});card("Сечение кабеля","Подбор зависит от нагрузки, материала, длины и способа прокладки.","▤",()->{});}
 void safety(){base("Электробезопасность");btn("← На главную",()->home());card("Перед работой","Отключите питание и исключите случайное повторное включение.","⚠",()->{});card("Проверьте напряжение","Пользуйтесь исправным указателем напряжения. Не полагайтесь только на выключатель.","✓",()->{});card("Защита","Автоматы, УЗО и заземление подбираются по проекту и нормам.","⛨",()->{});card("При сомнениях","Не работайте под напряжением. Обратитесь к квалифицированному электрику.","!",()->{});}
 void result(String t,double v,String unit){new AlertDialog.Builder(this).setTitle(t).setMessage(String.format(java.util.Locale.getDefault(),"%.2f %s",v,unit)).setPositiveButton("OK",null).show();}
 void msg(String s){new AlertDialog.Builder(this).setMessage(s).setPositiveButton("Понятно",null).show();}
}
